import { readFileSync } from "node:fs";
import { expect, it } from "vitest";
import { calendarHearingSchema } from "../src/shared/capiro/operations/legiwatch-calendar-schemas";
import { officialWatchSource } from "../src/features/modules/intelligence/legiwatch/hearings/official-media";

// Generated by actual LiveHearingsService.event() in Core's
// live-hearings-watch-media.spec.ts using injected synthetic database rows.
// Set this path for the two-repository check to consume the fresh Core output.
const input =
  process.env.LEGIWATCH_PLAYBACK_CONTRACT_PATH ??
  new URL("./fixtures/legiwatch-core-watch.json", import.meta.url);
const rows = (JSON.parse(readFileSync(input, "utf8")) as unknown[]).map((row) =>
  calendarHearingSchema.parse(row),
);

it("carries real Core live and archived projections through the FE schema into playable media", () => {
  expect(rows).toHaveLength(4);
  for (const row of rows) {
    const media = officialWatchSource(
      row.officialPlaybackUrl ?? row.officialPageUrl,
      row.officialWatchMedia,
    );
    expect(media.kind).toBe(
      ["synthetic-live", "synthetic-archived"].includes(row.id)
        ? "video"
        : "link",
    );
    expect(row.officialPageUrl).not.toMatch(/\.(mp4|m3u8)$/);
    expect(row.streamCandidates[0]).not.toHaveProperty("mediaUrl");
  }
});

it("falls back when a supplied watch projection expires or an older backend omits it", () => {
  const row = rows[0]!;
  expect(officialWatchSource(row.officialPlaybackUrl).kind).toBe("link");
  expect(
    officialWatchSource(row.officialPlaybackUrl, {
      ...row.officialWatchMedia!,
      expiresAt: "2000-01-01T00:00:00Z",
    }).kind,
  ).toBe("link");
  expect(
    officialWatchSource(row.officialPlaybackUrl, {
      ...row.officialWatchMedia!,
      url: "https://media.example.org/unsupported-player",
    }).kind,
  ).toBe("link");
});
